(37861, 'Leviticus 21:23', 'Leviticus', 21, 23, 'خو په دې خاطر چې په هغه کې جسماني عیب دی، هغه دې سپېڅلې پردې او د قربانۍ ځای ته نژدې رانه شي او زما سپېڅلی ځای او هرڅه چې په کې دي هغه دې نه ناپاکه کوي، ځکه چې زه څښتن یم او کاهنان سپېڅلي کوم.»', 'خو په دې خاطر چې په هغه کې جسمانی عیب دی، هغه دې سپېچلې پردې او د قربانی جای ته نژدې رانه شی او زما سپېچلی جای او هرچه چې په کې دی هغه دې نه ناپاکه کوی، جکه چې زه چشتن یم او کاهنان سپېچلی کوم.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_21_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37862, 'Leviticus 21:24', 'Leviticus', 21, 24, 'نو موسی دا هرڅه هارون او د هغه زامنو او ټولو اسراییلیانو ته وویل.', 'نو موسی دا هرچه هارون او د هغه زامنو او تولو اسراییلیانو ته وویل.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(37863, 'Exodus 37:1', 'Exodus', 37, 1, 'بزل ییل د اکاسۍ د لرګي څخه د لوظ صندوق جوړ کړ چې یو متر او لس سانتي اوږد ؤ، پنځه شپېته سانتي پلن ؤ او پنځه شپېته سانتي لوړ ؤ.', 'بزل ییل د اکاسی د لرګی چخه د لوظ صندوق جور کر چې یو متر او لس سانتی اوزد و، پنجه شپېته سانتی پلن و او پنجه شپېته سانتی لور و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37864, 'Exodus 37:2', 'Exodus', 37, 2, 'د هغه منځنۍ او باندینۍ برخې ته یې د سوچه سرو زرو پوښ ورکړ او د هغه ګردچاپېره څنډې یې د سرو زرو څخه جوړې کړې.', 'د هغه منجنی او باندینی برخې ته یې د سوچه سرو زرو پوش ورکر او د هغه ګردچاپېره چندې یې د سرو زرو چخه جورې کرې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37865, 'Exodus 37:3', 'Exodus', 37, 3, 'د هغه دپاره یې څلور د سرو زرو کړۍ ګانې جوړې کړې او د هغه په څلورو پایو باندې یې وتړلې، چې دوه کړۍ ګانې یې یوې خوا او دوه یې بلې خوا ته وې.', 'د هغه دپاره یې چلور د سرو زرو کری ګانې جورې کرې او د هغه په چلورو پایو باندې یې وترلې، چې دوه کری ګانې یې یوې خوا او دوه یې بلې خوا ته وې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37866, 'Exodus 37:4', 'Exodus', 37, 4, 'بیا هغه د اکاسۍ د لرګي څخه میلې جوړې کړې او د سرو زرو پوښ یې ورته ورکړ.', 'بیا هغه د اکاسی د لرګی چخه میلې جورې کرې او د سرو زرو پوش یې ورته ورکر.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37867, 'Exodus 37:5', 'Exodus', 37, 5, 'میلې یې هغو کړیو ته د وړلو دپاره ورننویستلې چې د صندوق په څنګونو کې وې.', 'میلې یې هغو کریو ته د ورلو دپاره ورننویستلې چې د صندوق په چنګونو کې وې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37868, 'Exodus 37:6', 'Exodus', 37, 6, 'د سوچه سرو زرو څخه یې د صندوق سرپوښ چې کفاره ورباندې ادا کیږي، جوړ کړ چې یو متر او لس سانتي اوږد ؤ او پنځه شپېته سانتي پلن ؤ.', 'د سوچه سرو زرو چخه یې د صندوق سرپوش چې کفاره ورباندې ادا کیزی، جور کر چې یو متر او لس سانتی اوزد و او پنجه شپېته سانتی پلن و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37869, 'Exodus 37:7', 'Exodus', 37, 7, 'بیا هغه د سرپوښ په خواوو باندې د ټکول شویو سرو زرو څخه دوه اسماني مخلوقات جوړ کړل.', 'بیا هغه د سرپوش په خواوو باندې د تکول شویو سرو زرو چخه دوه اسمانی مخلوقات جور کرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37870, 'Exodus 37:8', 'Exodus', 37, 8, 'یو یې په یوې خوا او دوهم ‎ یې په بلې خوا باندې جوړ کړ، په دوو خواوو باندې یې د سرپوښ سره اسماني مخلوقات د سرو زرو د یوې ټوټې څخه جوړ کړل.', 'یو یې په یوې خوا او دوهم ‎ یې په بلې خوا باندې جور کر، په دوو خواوو باندې یې د سرپوش سره اسمانی مخلوقات د سرو زرو د یوې توتې چخه جور کرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37871, 'Exodus 37:9', 'Exodus', 37, 9, 'د اسماني مخلوقاتو وزرونه د دې دپاره پورته خپاره وو چې په سرپوښ باندې سیوری وکړي. هغوی یو بل ته مخامخ وو او د سرپوښ خواته یې کتل.', 'د اسمانی مخلوقاتو وزرونه د دې دپاره پورته خپاره وو چې په سرپوش باندې سیوری وکری. هغوی یو بل ته مخامخ وو او د سرپوش خواته یې کتل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_9.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37872, 'Exodus 37:10', 'Exodus', 37, 10, 'بزل ییل د اکاسۍ د لرګي څخه یو داسې مېز جوړ کړ چې نوي سانتي اوږد ؤ، پنځه څلوېښت سانتي پلن ؤ او پنځه شپېته سانتي لوړ ؤ.', 'بزل ییل د اکاسی د لرګی چخه یو داسې مېز جور کر چې نوی سانتی اوزد و، پنجه چلوېشت سانتی پلن و او پنجه شپېته سانتی لور و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37873, 'Exodus 37:11', 'Exodus', 37, 11, 'بیا یې هغه ته د سوچه سرو زرو پوښ ورکړ او د هغه ګردچاپېره څنډې یې د سرو زرو څخه جوړې کړې.', 'بیا یې هغه ته د سوچه سرو زرو پوش ورکر او د هغه ګردچاپېره چندې یې د سرو زرو چخه جورې کرې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
