(37875, 'Exodus 37:13', 'Exodus', 37, 13, 'هغه د مېز دپاره څلور د سرو زرو کړۍ ګانې جوړې کړې او په هغو څلورو کنجونو کې یې وتړلې چېرته چې څلور پایې وې.', 'هغه د مېز دپاره چلور د سرو زرو کری ګانې جورې کرې او په هغو چلورو کنجونو کې یې وترلې چېرته چې چلور پایې وې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37876, 'Exodus 37:14', 'Exodus', 37, 14, 'کړۍ ګانې چوکاټ ته نژدې وې، د دې دپاره چې هغه میلې ونیسي چې د مېز په وړلو کې ورڅخه کار اخیستل کېده.', 'کری ګانې چوکات ته نژدې وې، د دې دپاره چې هغه میلې ونیسی چې د مېز په ورلو کې ورچخه کار اخیستل کېده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37877, 'Exodus 37:15', 'Exodus', 37, 15, 'د مېز د وړلو میلې د اکاسۍ د لرګي څخه جوړې شوې وې او د سرو زرو پوښ ورته ورکړل شوی ؤ.', 'د مېز د ورلو میلې د اکاسی د لرګی چخه جورې شوې وې او د سرو زرو پوش ورته ورکرل شوی و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37878, 'Exodus 37:16', 'Exodus', 37, 16, 'هغه ټول شیان چې په مېز باندې ایښودل کېدل یعنې کاسې، قابونه او د څښلو د نذرانو د تویولو دپاره منګي او جامونه د سوچه سرو زرو څخه جوړ شول.', 'هغه تول شیان چې په مېز باندې ایشودل کېدل یعنې کاسې، قابونه او د چشلو د نذرانو د تویولو دپاره منګی او جامونه د سوچه سرو زرو چخه جور شول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37879, 'Exodus 37:17', 'Exodus', 37, 17, 'بزل ییل د سوچه سرو زرو څخه یو څراغدان جوړ کړ او د هغه پایه او میله، د هغه د پیالو په شان ګلان، غوټۍ ګانې او ګلپاڼې یې د ټکول شویو سرو زرو څخه جوړ کړل. هغه ټول شیان د یوې ټوټې سرو زرو څخه جوړ شوي وو.', 'بزل ییل د سوچه سرو زرو چخه یو چراغدان جور کر او د هغه پایه او میله، د هغه د پیالو په شان ګلان، غوتی ګانې او ګلپانې یې د تکول شویو سرو زرو چخه جور کرل. هغه تول شیان د یوې توتې سرو زرو چخه جور شوی وو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37880, 'Exodus 37:18', 'Exodus', 37, 18, 'شپږ څانګې د څراغدان د څنګونو څخه غزېدلې وې، یعنې درې د یو څنګ څخه او درې د بل څنګ څخه.', 'شپز چانګې د چراغدان د چنګونو چخه غزېدلې وې، یعنې درې د یو چنګ چخه او درې د بل چنګ چخه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37881, 'Exodus 37:19', 'Exodus', 37, 19, 'درې پیالې چې شکلونه یې د بادام د ګل په شان وو، د غوټیو او ګلپاڼو سره په یوې څانګې باندې وې، درې په بلې څانګې باندې او په همدې ډول د شپږو واړو څانګو دپاره وې چې د څراغدان څخه غزېدلې وې.', 'درې پیالې چې شکلونه یې د بادام د ګل په شان وو، د غوتیو او ګلپانو سره په یوې چانګې باندې وې، درې په بلې چانګې باندې او په همدې دول د شپزو وارو چانګو دپاره وې چې د چراغدان چخه غزېدلې وې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37882, 'Exodus 37:20', 'Exodus', 37, 20, 'په خپله په څراغدان باندې څلور د بادام د ګل په شان پیالې وې، د غوټۍ ګانو او ګلپاڼو سره.', 'په خپله په چراغدان باندې چلور د بادام د ګل په شان پیالې وې، د غوتی ګانو او ګلپانو سره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37883, 'Exodus 37:21', 'Exodus', 37, 21, 'یوه غوټۍ د څانګو د اولې جوړې لاندې وه چې د څراغدان څخه غزېدلې وه، دوهمه غوټۍ د دوهمې جوړې لاندې وه او درېمه غوټۍ د درېمې جوړې لاندې وه یعنې ټولې شپږ څانګې وې.', 'یوه غوتی د چانګو د اولې جورې لاندې وه چې د چراغدان چخه غزېدلې وه، دوهمه غوتی د دوهمې جورې لاندې وه او درېمه غوتی د درېمې جورې لاندې وه یعنې تولې شپز چانګې وې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_37_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
